<?phpsession_start();// Check if user is logged inif (!isset($_SESSION['username'])) {    header("Location: login.php");    exit;}// DB connection$host = 'localhost';$dbname = 'moviedb';$db_user = 'root';$db_pass = '';$port = 3307;$conn = new mysqli($host, $db_user, $db_pass, $dbname, $port);if ($conn->connect_error) {    die("Connection failed: " . $conn->connect_error);}// Get current user$currentUsername = $_SESSION['username'];// Fetch current data$sql = "SELECT * FROM users WHERE username = ?";$stmt = $conn->prepare($sql);$stmt->bind_param("s", $currentUsername);$stmt->execute();$result = $stmt->get_result();if ($result->num_rows !== 1) {    echo "User not found.";    exit;}$row = $result->fetch_assoc();$updateMessage = "";if ($_SERVER["REQUEST_METHOD"] === "POST") {    $newUsername = trim($_POST["username"]);    $newEmail = trim($_POST["email"]);    $newBirthdate = $_POST["birthdate"];    $newPassword = $_POST["password"];    $newPasswordHash = password_hash($newPassword, PASSWORD_BCRYPT);    // Validate username length    if (strlen($newUsername) < 5 || strlen($newUsername) > 15) {        $updateMessage = "Username must be between 5 and 15 characters.";    }    // Validate age (must be 18 or older)    $birthDateObj = new DateTime($newBirthdate);    $today = new DateTime();    $age = $today->diff($birthDateObj)->y;    if ($age < 18) {        $updateMessage = "You must be at least 18 years old to update your profile.";    }    // If no validation errors, update user info    if (empty($updateMessage)) {        $updateSql = "UPDATE users SET username = ?, email = ?, birthdate = ?, password = ? WHERE username = ?";        $updateStmt = $conn->prepare($updateSql);        $updateStmt->bind_param("sssss", $newUsername, $newEmail, $newBirthdate, $newPasswordHash, $currentUsername);        if ($updateStmt->execute()) {            session_destroy(); // logout for re-login with new username            header("Location: login.php");            exit;        } else {            $updateMessage = "Error updating profile.";        }    }}$conn->close();?><!DOCTYPE html><html lang="en"><head>  <meta charset="UTF-8" />  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>  <title>Update Profile - Movielist</title>  <link rel="stylesheet" href="css/profile.css"></head><body class="dark-theme">  <div class="profile-container">    <h2>Update Profile Information</h2>    <?php if (!empty($updateMessage)): ?>      <div class="message"><?php echo htmlspecialchars($updateMessage); ?></div>    <?php endif; ?>    <form action="update_profile.php" method="POST">      <div class="profile-info">        <label>Username:</label>        <input type="text" name="username" value="<?php echo htmlspecialchars($row['username']); ?>" required minlength="5" maxlength="15" />      </div>      <div class="profile-info">        <label>Email:</label>        <input type="email" name="email" value="<?php echo htmlspecialchars($row['email']); ?>" required />      </div>      <div class="profile-info">        <label>Date of Birth:</label>        <input type="date" name="birthdate" value="<?php echo htmlspecialchars($row['birthdate']); ?>" required />      </div>      <div class="profile-info">        <label>New Password:</label>        <input type="password" name="password" required />      </div>      <button type="submit">Update Profile</button>    </form>    <div class="back-button-container">      <a href="profile.php" class="back-button">Back to Profile</a>    </div>  </div></body></html>